// Источник: web-тест .qa/e2e/tests/splash/sp-01-brand-promise-single-cta.spec.ts, план .qa/e2e/specs/splash.md, кейс .qa/tests/splash/SP-01-brand-promise-single-cta.md
// Тикет #6a86f800. Splash виден только гостю: тест выходит из аккаунта («התנתקות») и в конце входит снова через login() (тестовый OTP из .qa/accounts.env).
import { $$, expect, driver } from '@wdio/globals';
import { byText, tapLabel, tapText, expectVisibleText, scrollToText } from '../../helpers/ui.ts';
import { ensureAppReady, isLoggedIn, toHome } from '../../helpers/app.ts';

/** Выход: профиль → «התנתקות» (+ подтверждение, если есть) → splash. */
async function logout() {
  await toHome();
  await tapLabel('מעבר לפרטים שלי');
  await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });
  await (await scrollToText('התנתקות')).click();
  await driver.waitUntil(async () => {
    if (await byText('בואו נתחיל').isDisplayed().catch(() => false)) return true;
    const confirm = await byText('התנתקות');
    if (await confirm.isDisplayed().catch(() => false)) await confirm.click().catch(() => {});
    return false;
  }, { timeout: 20000, interval: 700, timeoutMsg: 'после «התנתקות» не открылся splash' });
}
/** Вернуться к splash/входу и войти снова (login() начинает со splash или экрана номера). */
async function restoreLogin() {
  for (let i = 0; i < 4; i++) {
    if (await isLoggedIn()) return;
    if (await byText('בואו נתחיל').isDisplayed().catch(() => false)) break;
    if (await byText('כניסה דרך מספר נייד').isDisplayed().catch(() => false)) break;
    await driver.back();
  }
  await ensureAppReady();
}

describe('Splash — экран входа', () => {
  before(async () => { await logout(); });
  after(async () => { await restoreLogin(); });

  it('SP-01 Splash: бренд, обещание, пасук, одна кнопка → экран номера #6a86f800 @prod-safe', async () => {
    // 1–2. Splash: тексты, кнопка «בואו נתחיל», полей ввода нет.
    await (await byText('בואו נתחיל')).waitForDisplayed();
    await expectVisibleText('אור הגאולה');
    await expectVisibleText('ה\' רֹעִי לֹא אֶחְסָר');
    await expectVisibleText('ברוכים הבאים לאור הגאולה');
    await expectVisibleText('התפילה החכמה שתלווה אותך בכל מקום ובכל זמן');
    const inputs = driver.isAndroid
      ? await $$('android=new UiSelector().className("android.widget.EditText")')
      : await $$('-ios class chain:**/XCUIElementTypeTextField');
    expect(inputs.length).toBe(0);

    // 3. «בואו נתחיל» → экран входа по номеру.
    await tapText('בואו נתחיל');
    await (await byText('כניסה דרך מספר נייד')).waitForDisplayed({ timeout: 20000 });
  });
});
